<script>
(() => {
    const body = document.body;
    const sectionCover = document.getElementById('section-cover');
    const openButton = document.getElementById('tombol-buka');
    const invitationAudio = document.getElementById('song');
    const defaultOnScroll = window.onscroll;
    const disableScrolling = () => {
        const scrollX = window.scrollX;
        const scrollY = window.scrollY;
        window.onscroll = () => window.scrollTo(scrollX, scrollY);
    };
    const enableScrolling = () => { window.onscroll = defaultOnScroll; };
    const lockSection = () => {
        disableScrolling();
        body.style.position = 'fixed';
        body.style.overflowY = 'scroll';
        body.style.height = '100vh';
        if (sectionCover) sectionCover.style.width = '100vw';
    };
    const unlockSection = () => {
        enableScrolling();
        body.style.position = '';
        body.style.overflowY = '';
        body.style.height = '';
        if (sectionCover) sectionCover.style.width = '';
        if (openButton) openButton.style.display = 'none';
    };
    const playInvitationAudio = () => invitationAudio?.play().catch(() => {});
    window.addEventListener('beforeunload', () => window.scrollTo(0, 0));
    lockSection();
    openButton?.addEventListener('click', () => {
        unlockSection();
        playInvitationAudio();
    });
    const systemForm = document.getElementById('netflix-system-form');
    const attendance = systemForm?.querySelector('[name="rsvp_status"]');
    const guestCount = systemForm?.querySelector('.saic-wrap-guest');
    const guestCountSelect = systemForm?.querySelector('[name="party_size"]');
    const syncGuestCount = () => {
        const isAttending = attendance?.value === 'attending';
        if (guestCount) guestCount.style.display = isAttending ? 'block' : 'none';
        if (guestCountSelect) guestCountSelect.required = Boolean(isAttending);
    };
    attendance?.addEventListener('change', syncGuestCount);
    syncGuestCount();
    systemForm?.addEventListener('submit', async (event) => {
        event.preventDefault();
        const submitButton = document.getElementById('netflix-system-submit');
        const status = document.getElementById('saic-comment-status-215117');
        if (submitButton) submitButton.disabled = true;

        try {
            const rsvpData = new FormData();
            ['_token', 'rsvp_status', 'party_size'].forEach((name) => {
                const value = systemForm.querySelector(`[name="${name}"]`)?.value;
                if (value !== undefined && value !== '') rsvpData.append(name, value);
            });
            const response = await fetch(systemForm.dataset.rsvpAction, {
                method: 'POST',
                body: rsvpData,
                headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
            });
            if (!response.ok) throw new Error('RSVP request failed');
            HTMLFormElement.prototype.submit.call(systemForm);
        } catch {
            if (status) status.textContent = 'Jawaban belum berhasil dikirim. Silakan coba lagi.';
            if (submitButton) submitButton.disabled = false;
        }
    });
    const revealElements = (selector) => {
        const windowHeight = window.innerHeight;
        document.querySelectorAll(selector).forEach((element) => {
            const isVisible = element.getBoundingClientRect().top < windowHeight - 150;
            element.classList.toggle('active', isVisible);
            if (isVisible) element.classList.remove('elementor-invisible');
        });
    };
    const animatedElements = '.muncul, .muncul-kiri, .muncul-kanan, .zoom, .elementor-invisible';
    window.addEventListener('scroll', () => revealElements(animatedElements), { passive: true });
    window.addEventListener('load', () => revealElements(animatedElements), { once: true });
    const countdown = document.querySelector('.elementor-countdown-wrapper[data-date]');
    if (countdown) {
        const target = Number(countdown.dataset.date) * 1000;
        const updateCountdown = () => {
            let remaining = Math.max(0, target - Date.now());
            [['days', 86400000], ['hours', 3600000], ['minutes', 60000], ['seconds', 1000]].forEach(([unit, size]) => {
                const value = Math.floor(remaining / size);
                remaining %= size;
                const digit = countdown.querySelector(`.elementor-countdown-${unit}`);
                if (digit) digit.textContent = String(value).padStart(2, '0');
            });
        };
        updateCountdown();
        window.setInterval(updateCountdown, 1000);
    }
    const audio = document.querySelector('#song');
    const playControl = document.querySelector('#wds_audio_play');
    const pauseControl = document.querySelector('#wds_audio_pause');
    window.netflixInvitationAudio = audio;
    const updateAudioControls = () => {
        if (playControl) playControl.hidden = !audio?.paused;
        if (pauseControl) pauseControl.hidden = !audio || audio.paused;
    };
    playControl?.addEventListener('click', () => audio?.play().then(updateAudioControls).catch(() => {}));
    pauseControl?.addEventListener('click', () => { audio?.pause(); updateAudioControls(); });
    audio?.addEventListener('play', updateAudioControls);
    audio?.addEventListener('pause', updateAudioControls);
    updateAudioControls();
    const giftPanel = document.getElementById('amplop');
    const showGiftButton = document.getElementById('btnAmplop');
    const hideGiftButton = document.getElementById('btn-hide');
    if (giftPanel) giftPanel.style.display = 'none';
    if (hideGiftButton) hideGiftButton.style.display = 'none';
    showGiftButton?.addEventListener('click', () => {
        if (hideGiftButton) hideGiftButton.style.display = 'block';
        showGiftButton.style.display = 'none';
        if (giftPanel) giftPanel.style.display = 'block';
    });
    hideGiftButton?.addEventListener('click', () => {
        if (hideGiftButton) hideGiftButton.style.display = 'none';
        if (showGiftButton) showGiftButton.style.display = 'block';
        if (giftPanel) giftPanel.style.display = 'none';
    });
    const lightbox = document.createElement('div');
    lightbox.className = 'netflix-gallery-lightbox';
    lightbox.innerHTML = '<button type="button" aria-label="Tutup">×</button><img alt="Foto galeri">';
    document.body.append(lightbox);
    const lightboxImage = lightbox.querySelector('img');
    document.querySelectorAll('#gallery .e-gallery-item').forEach((item) => item.addEventListener('click', (event) => {
        event.preventDefault();
        lightboxImage.src = item.getAttribute('href');
        lightbox.classList.add('is-open');
    }));
    lightbox.addEventListener('click', (event) => {
        if (event.target === lightbox || event.target.closest('button')) lightbox.classList.remove('is-open');
    });
})();
</script>
JAVASCRIPT;
